const queueCount=document.querySelector("#queueCount"),playingCount=document.querySelector("#playingCount"),queueList=document.querySelector("#queueList");
function renderQueue(data){queueCount.textContent=new Intl.NumberFormat("pt-BR").format(data.waitingCount||0);playingCount.textContent=new Intl.NumberFormat("pt-BR").format(data.playingCount||0);const players=(data.players||[]).slice(0,5);if(!players.length){queueList.innerHTML='<div class="queue-empty">A fila está aberta. Compre um passe para garantir sua posição.</div>';return}queueList.replaceChildren(...players.map(player=>{const item=document.createElement("div");item.className="queue-player";const position=document.createElement("span");position.textContent=player.status==="playing"?"▶":`#${player.position}`;const copy=document.createElement("div"),name=document.createElement("b"),meta=document.createElement("small");name.textContent=player.name;meta.textContent=player.status==="playing"?"Jogando agora":`Posição ${player.position} de ${player.total}`;copy.append(name,meta);const duration=document.createElement("em");duration.textContent=`${player.durationMinutes} min`;item.append(position,copy,duration);return item}))}
async function refreshQueue(){try{const response=await fetch("/api/cloud-queue",{cache:"no-store"});if(!response.ok)throw new Error("Fila indisponível");renderQueue(await response.json())}catch{queueCount.textContent="—";playingCount.textContent="—";queueList.innerHTML='<div class="queue-empty">A fila está se reconectando…</div>'}}
refreshQueue();setInterval(refreshQueue,12000);
